import{z as B,x as o,o as E,c as n,q as e,j as r,D as l,d as s,s as A,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"深度图、点云与高斯溅射写出","description":"","frontmatter":{"title":"深度图、点云与高斯溅射写出","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/atlas-3d-writeout.md","filePath":"llm/atlas-3d-writeout.md","lastUpdated":1791063341000}'),d={name:"llm/atlas-3d-writeout.md"};function p(m,a,D,h,_,c){const t=o("Mermaid");return E(),n("div",null,[a[2]||(a[2]=e('<h1 id="深度图、点云与高斯溅射写出" tabindex="-1">深度图、点云与高斯溅射写出 <a class="header-anchor" href="#深度图、点云与高斯溅射写出" aria-label="Permalink to &quot;深度图、点云与高斯溅射写出&quot;">​</a></h1><div class="epigraph"><p>Atlas 原生同时操作二维图像帧与三维深度图，因而可以把世界写成点云或三维高斯溅射，而不只是一段好看的视频。</p><footer>—— World Labs Team, Atlas: A World Model for Spatial Intelligence, 2026</footer></div><p>世界模型若只能出 RGB 帧，下游仍要另跑深度估计、另做多视几何、再手工进游戏引擎。World Labs 的 Atlas 把深度图当成与图像对等的模态：每个深度图同样锚定在显式相机位姿上，进入同一套<a href="/llm/atlas-spatial-context">空间上下文</a>。写出路径因此从「生成画面」变成「生成可度量的三维对象」——先有每像素深度，再反投影成点云，再把点云补全、转成可实时渲染的三维高斯溅射（3D Gaussian Splatting, 3DGS）。这与 Marble 产品线共用溅射表示，但本篇只写 Atlas 这条写出链，不把 Marble 的网格导出和编辑器复述成同一套 API。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>机器人、游戏、视效要的往往不是一张新视角图，而是一份能被别的系统接着用的几何。新视角合成可以在像素域里「看起来对」，却给不出碰撞、尺度和可重渲染的资产。传统管线把问题拆开：多视立体或 NeRF 一类方法估几何，高斯溅射或网格负责显示。拆开的代价是误差在接口处累积：深度尺度漂了，溅射就对不齐；帧间深度抖动，点云就出现层状重影。</p><p>Atlas 面对的是另一条约束：它是<a href="/llm/atlas-ardt">多模态自回归扩散</a>，上下文里已经有带位姿的图像。若深度只作为后处理，模型在去噪图像时学到的三维一致性无法被下游读取。需要一种写出：深度与 RGB 在同一套条件上联合生成，再把深度变成点，把点变成可渲染的溅射，中间尽量少换坐标系。</p><h3 id="三种写出对象不是同一信息量" tabindex="-1">三种写出对象不是同一信息量 <a class="header-anchor" href="#三种写出对象不是同一信息量" aria-label="Permalink to &quot;三种写出对象不是同一信息量&quot;">​</a></h3><p>深度图 \\(D\\in\\mathbb{R}^{H\\times W}\\) 仍绑在某一相机上，是 2.5D。点云把许多视图的深度反投影到世界系，得到 \\(\\{X_i\\}\\)，开始有跨视几何，但仍是无拓扑的离散样本。三维高斯溅射再给每个原语一组均值、协方差、不透明度和球谐颜色，才能在任意新相机下可微光栅化。从 \\(D\\) 到点云是几何聚合；从点云到溅射是表示升级——补洞、抗锯齿、让实时渲染成立。World Labs 写得很直白：点云估计场景几何，溅射才让这份几何可用。</p><p><span class="marginnote">「2.5D」指深度图只记录「从这一台相机看出去」的表面距离：有正面，没有背面和被挡住的侧面。它相当于把三维压扁进一张图，所以叫半个三维；想补齐其余面，就得换机位再看，或让模型想象。</span></p><p><span class="marginnote">不要把「能出深度」写成「能出网格」。Atlas 公开发布材料确认的显式三维写出是深度、点云与 3DGS；原生网格、UV、材质与碰撞体并未作为 Atlas 的原生输出披露。网格若出现在产品里，更可能来自 Marble 一侧的导出，而不是这篇写出链的最后一步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记相机外参为 \\((R,t)\\)、内参为 \\(K\\)。像素 \\((u,v)\\) 上的深度 \\(D(u,v)\\) 反投影为</p> \\[X = R^\\top\\bigl(D(u,v)\\,K^{-1}\\tilde{u}-t\\bigr),\\qquad \\tilde{u}=(u,v,1)^\\top. \\]<p><span class="marginnote">数字实例：设焦距 \\(f=500\\) 像素、像素 \\((320,240)\\)、深度 4 米，该点在相机系里大约是 \\(\\bigl((320-c_x)\\cdot 4/500,\\ (240-c_y)\\cdot 4/500,\\ 4\\bigr)\\) 米。深度若偏差 0.1 米，这点就沿视线整体挪动 10 厘米——深度尺度错，点云就跟着整体错。</span></p><p>单帧给出一层点；多帧把 \\(\\{X\\}\\) 并入同一世界系。视频路径上，Atlas 对每一帧预测深度再融合；单图路径上，它联合生成新视角及其几何，再把未见区域补上。无论哪条路径，深度与 RGB 都条件在同一位姿上，避免「图是生成的、深度是另一套网络估的」那种错位。</p><p>溅射阶段把点云提升为高斯集合 \\(\\{(\\mu_j,\\Sigma_j,\\alpha_j,c_j)\\}\\)。渲染时，相机 \\(P\\) 把三维高斯投影到图像平面，按深度排序做 alpha 合成。这正是 Kerbl 等人 2023 年三维高斯溅射的表示；Atlas 的贡献不在发明溅射，而在让同一 omni 模型直接写出能送进该表示的几何，并与 Marble 的溅射世界对齐，从而可以在设备端高分辨率、高帧率渲染。</p>',16)),(E(),r(i,null,{default:l(()=>[A(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTX%5B%22%E5%B8%A6%E4%BD%8D%E5%A7%BF%E7%9A%84%E5%9B%BE%E5%83%8F%E4%B8%8E%E6%96%87%E6%9C%AC%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%20--%3E%20GEN%5B%22%E8%81%94%E5%90%88%E7%94%9F%E6%88%90%20RGB%20%E4%B8%8E%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20GEN%20--%3E%20D%5B%22%E9%80%90%E5%B8%A7%E6%B7%B1%E5%BA%A6%E5%9B%BE%22%5D%0A%20%20D%20--%3E%20PC%5B%22%E5%8F%8D%E6%8A%95%E5%BD%B1%E8%9E%8D%E5%90%88%E7%82%B9%E4%BA%91%22%5D%0A%20%20PC%20--%3E%20FILL%5B%22%E8%A1%A5%E5%85%A8%E6%9C%AA%E8%A7%81%E5%8C%BA%E5%9F%9F%22%5D%0A%20%20FILL%20--%3E%20GS%5B%22%E4%B8%89%E7%BB%B4%E9%AB%98%E6%96%AF%E6%BA%85%E5%B0%84%E5%9C%BA%E6%99%AF%22%5D%0A%20%20GS%20--%3E%20REN%5B%22%E8%AE%BE%E5%A4%87%E7%AB%AF%E5%AE%9E%E6%97%B6%E6%B8%B2%E6%9F%93%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="单图生成与视频重建两条入口" tabindex="-1">单图生成与视频重建两条入口 <a class="header-anchor" href="#单图生成与视频重建两条入口" aria-label="Permalink to &quot;单图生成与视频重建两条入口&quot;">​</a></h3><p>单张输入图只能约束可见表面。Atlas 的做法是：在空间上下文里按新位姿继续写出视图，同时估这些视图的深度，等于用生成补齐多视立体所缺的观测。视频输入则相反：每一帧已是对真实空间的采样，模型预测每帧深度并融合，想象主要用于相机从未扫到的缝。两条入口共用深度模态，因此写出格式相同，不需要「生成专用」和「重建专用」两套导出器。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>深度作为原生模态，意味着 Transformer 序列里深度块与图像块一样，前面有相机位姿条件。自回归一步可以是「下一张图」，也可以是「下一张深度」；<a href="/llm/atlas-rectified-flow">rectified flow</a> 在潜空间里去噪的是连续场，深度与 RGB 都是高维连续对象，适合同一扩散骨架。联合去噪让对应像素的颜色与 \\(D(u,v)\\) 共享噪声日程与空间上下文，几何一致性是训练目标的一部分，而不是事后拟合。</p><p>点云融合依赖位姿已知。Atlas 把位姿当<a href="/llm/atlas-native-camera">原生输入</a>而不是从图里估，写出时外参误差不来自另一套 SfM 的漂移——至少在「用户给定轨迹」的生成设定下是这样。真实视频重建仍可能需要把捕获时的位姿估计进来；公开材料没有把 Atlas 内部的位姿求解器写成可复现算法，工程上应把「输入位姿的质量」当成写出质量的外生变量。</p><p><span class="marginnote">反投影公式假定深度与 \\(K\\) 使用同一相机模型。若生成分辨率与内参标注不一致，点云会整体缩放或畸变。评估写出时要同时看深度图和反投影后的点，只看彩色渲染会把内参错误藏进「看起来立体」。</span></p><h3 id="为何溅射而不是停在点云" tabindex="-1">为何溅射而不是停在点云 <a class="header-anchor" href="#为何溅射而不是停在点云" aria-label="Permalink to &quot;为何溅射而不是停在点云&quot;">​</a></h3><p>点云能检查几何，却几乎不能当最终显示：稀疏、有孔、没有面片上的反锯齿。溅射用各向异性高斯覆盖空洞，并在新视角下可微渲染，适合浏览和预览。World Labs 强调这与 Marble 同一表示，产品含义是：Atlas 写出的世界可以进入已有溅射工具链，而不必先变成网格。对需要刚体碰撞或动画绑定的流程，溅射仍不够，必须另接网格化，那已超出本篇的写出定义。</p>',8)),(E(),r(i,null,{default:l(()=>[A(t,{id:"mermaid-69",class:"mermaid",graph:"flowchart%20LR%0A%20%20D%5B%22%E6%B7%B1%E5%BA%A6%E5%9B%BE%20D%5Cn2.5D%20%C2%B7%20%E7%BB%91%E5%AE%9A%E5%8D%95%E7%9B%B8%E6%9C%BA%22%5D%20--%3E%7C%22%E5%8F%8D%E6%8A%95%E5%BD%B1%20%2B%20%E5%A4%9A%E5%B8%A7%E8%9E%8D%E5%90%88%22%7C%20PC%5B%22%E7%82%B9%E4%BA%91%20%7BX_i%7D%5Cn%E4%B8%96%E7%95%8C%E7%B3%BB%20%C2%B7%20%E6%97%A0%E6%8B%93%E6%89%91%22%5D%0A%20%20PC%20--%3E%7C%22%E8%A1%A5%E6%B4%9E%20%2B%20%E8%A1%A8%E7%A4%BA%E5%8D%87%E7%BA%A7%22%7C%20GS%5B%223DGS%20%E9%AB%98%E6%96%AF%E9%9B%86%5Cn%E5%9D%87%E5%80%BC%20%2F%20%E5%8D%8F%E6%96%B9%E5%B7%AE%20%2F%20%E4%B8%8D%E9%80%8F%E6%98%8E%E5%BA%A6%20%2F%20%E7%90%83%E8%B0%90%E8%89%B2%22%5D%0A%20%20GS%20--%3E%20R%5B%22%E4%BB%BB%E6%84%8F%E6%96%B0%E8%A7%86%E8%A7%92%5Cn%E5%8F%AF%E5%BE%AE%E5%AE%9E%E6%97%B6%E6%B8%B2%E6%9F%93%22%5D%0A%20%20D%20-.-%3E%7C%22%E5%8F%AA%E6%9C%89%E5%8D%95%E8%A7%86%E5%8F%AF%E8%A7%81%E8%A1%A8%E9%9D%A2%22%7C%20X1%5B%22%E6%97%A0%E6%B3%95%E8%B7%A8%E8%A7%86%E5%AF%B9%E9%BD%90%22%5D%0A%20%20PC%20-.-%3E%7C%22%E7%A8%80%E7%96%8F%E6%9C%89%E5%AD%94%E6%97%A0%E9%9D%A2%E7%89%87%22%7C%20X2%5B%22%E4%B8%8D%E8%83%BD%E5%BD%93%E6%9C%80%E7%BB%88%E6%98%BE%E7%A4%BA%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p><span class="marginnote">直觉类比：3DGS 像在空间里撒了几十万到几百万个半透明的「棉花球」，每个球自带颜色、朝向和胖瘦；渲染就是按远近把球叠加成图。球够密看起来就是连续表面——但底下并没有真正的「面」，所以物理引擎要的碰撞体它给不了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>写出几何不等于度量重建。单视图路径上，被遮挡面与画外结构来自模型的世界知识，点云里那些点是想象，不是激光测量。多视图可以压低想象比例，但不能自动给出绝对尺度、相机标定残差或材料。把溅射场景送进物理引擎前，应另做尺度对齐与碰撞简化，而不是假设 \\(\\mu_j\\) 已是米制。</p><p>深度模态的数值范围、是否度量深度、视差与正交相机如何编码，官方未给模型卡。复现实验应把深度当成「与 RGB 对齐的稠密场」，用相对误差和跨视重投影来评，而不是直接拿消费级深度相机的毫米误差去比。点云融合若不做可见性与一致性过滤，重复观测会堆出厚壳；公开演示看起来干净，不代表默认写出没有离群点。</p><p><span class="marginnote">3DGS 的优化文献通常从多视图像拟合高斯。Atlas 是模型直接写出溅射场景，拟合迭代次数、球谐阶数、是否再做一次经典 3DGS 精修，均未披露。下游若质量不够，合法操作是把写出的点云或溅相当初始化，再跑 Kerbl 式优化，而不是声称 Atlas 已经替代了那篇 SIGGRAPH 论文里的训练循环。</span></p><p>时间维上，逐帧深度再融合会把动态物体拉出鬼影。本篇的写出默认偏静态或准静态场景；动态的时空一致性交给<a href="/llm/atlas-video-as-frames">视频作为带位姿的帧序列</a>与后续的<a href="/llm/atlas-video-reframe">reframing</a>，不要在点云里假装有4D 高斯。许可与早鸟访问同样构成边界：截至 2026 年 9 月的发布说明，Atlas 进入精选合作方早鸟，公开材料是博客与演示，不是可下载的写出权重。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Atlas 把深度图与 RGB 同为带位姿的模态，写出链是深度 → 点云 → 三维高斯溅射。</li><li>单图路径联合生成新视角与几何；视频路径逐帧估深度再融合，未见区域由模型补全。</li><li>点云用于聚合几何，溅射用于可渲染、可接入 Marble 的同一表示；原生网格不是这条链已确认的终点。</li><li>反投影依赖内参与位姿；写出质量首先受空间上下文与位姿质量约束。</li><li>单视写出必然混有想象几何，不可当作测量点云。</li><li>溅射便于预览，不自动提供碰撞、材质与拓扑。</li><li>出处：World Labs Team，<em>Atlas: A World Model for Spatial Intelligence</em>，World Labs Blog，2026；溅射表示见 Kerbl 等，<em>3D Gaussian Splatting for Real-Time Radiance Field Rendering</em>，SIGGRAPH 2023。</li></ul>',8))])}const b=B(d,[["render",p]]);export{f as __pageData,b as default};
